function renderGraphModal() {
  const person = state.graphEmployee;
  if (!person) return '';
  return `<div class="modal-backdrop" data-close-graph><section class="modal" role="dialog" aria-modal="true" aria-labelledby="graph-title"><header class="modal-header"><div><h2 id="graph-title">${escapeHTML(person.name)} · Skill graph</h2><p>${escapeHTML(person.title)} · ${escapeHTML(person.department)} · ${person.experienceYears} years of experience</p></div><button class="modal-close" data-action="close-graph" aria-label="Close">${icon('close')}</button></header><div class="modal-body"><div class="section-heading" style="margin-top:0"><div><h2>Skill evidence graph</h2><p>Connected skills, proficiency and relevant work</p></div></div>${renderGraphSvg(person)}<div class="section-heading"><div><h2>Evidence and availability</h2></div><span class="badge ${person.workload >= 85 ? 'warn' : ''}">${100 - person.workload}% capacity</span></div><div class="tag-line">${skillChips(person.skills)}</div><div class="separator"></div><div class="domain-note"><strong>Projects:</strong> ${person.projects.map((project) => `${escapeHTML(project.name)} (${escapeHTML(project.domain)} · ${project.year})`).join(' · ')}<br><strong>Certifications:</strong> ${person.certifications.map((cert) => escapeHTML(cert.name)).join(' · ') || 'None listed'}<br><strong>Evidence:</strong> ${escapeHTML(person.evidence || 'Project and experience evidence')}</div><div class="section-heading"><div><h2>Projects</h2></div></div>${person.projects.map((project) => `<div class="opportunity-item"><div><div class="opportunity-title">${escapeHTML(project.name)}</div><div class="opportunity-sub">${escapeHTML(project.domain)} · ${escapeHTML(project.year)}</div><div class="opportunity-requirements">${project.technologies.map((technology) => `<span class="skill-tag">${escapeHTML(technology)}</span>`).join('')}</div></div><span class="badge">${escapeHTML(project.technologies.length)} skills</span></div>`).join('')}</div></section></div>`;
}
async function refreshDashboard(renderPage = true) {
  state.dashboard = await API('/api/dashboard');
  const learning = state.dashboard.learning;
  state.timerSince = Date.now();
  if (renderPage) render();
  startTimerDisplay();
}
async function runSearch(query) {
  state.searchText = query;
  state.matchFilter = 'All';
  state.matchesVisible = 12;
  const button = document.querySelector('#talent-search button[type="submit"]');
  if (button) { button.disabled = true; button.innerHTML = '<span class="spinner"></span> Searching'; }
  try { state.matches = await post('/api/hr/search', { query }); document.getElementById('candidate-results').innerHTML = renderCandidateResults(); }
  catch (error) { notify(error.message, true); }
  finally { if (button) { button.disabled = false; button.innerHTML = `${icon('spark')} Find talent`; } }
}
function applyEstimatedLearningTime() {
  const duration = state.dashboard?.course?.durationHours;
  if (duration === undefined) return;
  const timerPanel = document.querySelector('#learning-content .timer-panel');
  if (timerPanel) timerPanel.innerHTML = `<div class="timer-label">Estimated learning time</div><div class="timer-value">${escapeHTML(duration)}h</div><p>Estimated duration for this course.</p>`;
  const snapshotLabel = [...document.querySelectorAll('.stat-top > span')].find((item) => item.textContent.trim() === 'Actual time spent');
  if (snapshotLabel) {
    snapshotLabel.textContent = 'Estimated learning time';
    const snapshot = snapshotLabel.closest('.surface');
    snapshot.querySelector('.stat-number').textContent = `${duration}h`;
    snapshot.querySelector('.stat-foot').textContent = 'Estimated course duration';
  }
}
function startTimerDisplay() { window.clearInterval(state.timerBase); }
async function updateLearningView() { await refreshDashboard(false); const target = document.getElementById('page-content'); if (target) { target.innerHTML = renderSection(); applyEstimatedLearningTime(); } else render(); startTimerDisplay(); }
appRoot.addEventListener('click', async (event) => {
  const route = event.target.closest('[data-route]');
  if (route) { state.section = route.dataset.route; if (state.user && !state.dashboard) await refreshDashboard(false); render(); startTimerDisplay(); return; }
  const authMode = event.target.closest('[data-auth-mode]');
  if (authMode) { state.authMode = authMode.dataset.authMode; render(); return; }
  const graphButton = event.target.closest('[data-graph]');
  if (graphButton) {
    try { const graph = await API(`/api/employees/${encodeURIComponent(graphButton.dataset.graph)}/graph`); state.graphEmployee = graph.employee; render(); }
    catch (error) { notify(error.message, true); }
    return;
  }
  const profileButton = event.target.closest('[data-profile]');
  if (profileButton) { const match = state.matches?.matches.find((person) => person.id === profileButton.dataset.profile); if (match) { state.graphEmployee = match; render(); } return; }
  const matchFilter = event.target.closest('[data-match-filter]');
  if (matchFilter) { state.matchFilter = matchFilter.dataset.matchFilter; state.matchesVisible = 12; document.getElementById('candidate-results').innerHTML = renderCandidateResults(); return; }
  if (event.target.closest('[data-match-more]')) { state.matchesVisible += 12; document.getElementById('candidate-results').innerHTML = renderCandidateResults(); return; }
  const interestButton = event.target.closest('[data-interest]');
  if (interestButton) { try { await post(`/api/openings/${encodeURIComponent(interestButton.dataset.interest)}/interest`, {}); await refreshDashboard(false); render(); notify('Your interest has been shared with the project team.'); } catch (error) { notify(error.message, true); } return; }
  const moduleButton = event.target.closest('[data-module]');
  if (moduleButton) { try { await post(`/api/learning/modules/${moduleButton.dataset.module}`, {}); await updateLearningView(); notify('Module completed. Your course progress is updated.'); } catch (error) { notify(error.message, true); } return; }
  const action = event.target.closest('[data-action]')?.dataset.action;
  if (action === 'invite-employee') { state.modal = 'invite'; render(); document.getElementById('invite-name')?.focus(); }
  if (action === 'notifications') { try { const [n, e] = await Promise.all([API('/api/notifications'), API('/api/evidence')]); state.notifications = n.notifications; state.evidenceTasks = e.tasks; if (state.user.role === 'hr') { const settings = await API('/api/hr/settings'); state.evidenceDueDays = settings.evidenceDueDays; state.allowedEmailDomains = settings.allowedEmailDomains || []; } state.modal = 'notifications'; render(); } catch (error) { notify(error.message, true); } }
  if (action === 'read-all') { try { await post('/api/notifications/read-all', {}); state.notifications = (await API('/api/notifications')).notifications; render(); } catch (error) { notify(error.message, true); } }
  const readButton = event.target.closest('[data-read-notification]'); if (readButton) { try { await post(`/api/notifications/${encodeURIComponent(readButton.dataset.readNotification)}/read`, {}); const result = await API('/api/notifications'); state.notifications = result.notifications; state.modal = 'notifications'; render(); } catch (error) { notify(error.message, true); } return; }
  const reviewButton = event.target.closest('[data-review-task]'); if (reviewButton) { const decision = reviewButton.dataset.decision; const reason = decision === 'Approved' ? '' : (window.prompt(`Reason for ${decision.toLowerCase()}:`) || '').trim(); if (decision !== 'Approved' && !reason) { notify('A reason is required for rejection or requested changes.', true); return; } try { await post(`/api/hr/evidence/${encodeURIComponent(reviewButton.dataset.reviewTask)}/review`, { decision, reason }); const [n, e] = await Promise.all([API('/api/notifications'), API('/api/evidence')]); state.notifications = n.notifications; state.evidenceTasks = e.tasks; render(); notify(`Evidence ${decision.toLowerCase()}.`); } catch (error) { notify(error.message, true); } return; }
  if (action === 'logout') { await post('/api/logout', {}); state.user = null; state.dashboard = null; state.matches = null; state.section = 'dashboard'; render(); }
  if (action === 'open-opening') { state.modal = 'opening'; render(); document.getElementById('opening-title')?.focus(); }
  if (action === 'close-modal') { state.modal = null; render(); }
  if (action === 'close-graph') { state.graphEmployee = null; render(); }
  if (action === 'view-own-graph' && state.dashboard.employee) { try { const graph = await API(`/api/employees/${encodeURIComponent(state.dashboard.employee.id)}/graph`); state.graphEmployee = graph.employee; render(); } catch (error) { notify(error.message, true); } }
  if (action === 'start-learning' || action === 'pause-learning') {
    try { const result = await post('/api/learning/session', { action: action === 'start-learning' ? 'start' : 'pause' }); state.dashboard.learning.timeSpentHours = result.timeSpentHours; state.dashboard.learning.sessionStartedAt = result.running ? Date.now() : null; state.timerSince = Date.now(); await updateLearningView(); notify(result.running ? 'Learning session started. Time is now tracking.' : 'Session paused. Time saved.'); }
    catch (error) { notify(error.message, true); }
  }
  if (action === 'earn-certificate') { try { await post('/api/learning/certification', {}); await updateLearningView(); notify('Certificate earned and added to your learning evidence.'); } catch (error) { notify(error.message, true); } }
  if (action === 'evaluate-learning') { try { const result = await post('/api/learning/evaluate', {}); state.dashboard.learning.achievement = result.evaluation; state.dashboard.employee = result.employee; await updateLearningView(); notify(`Learning achievement recorded: ${result.evaluation.achievement}%.`); } catch (error) { notify(error.message, true); } }
  if (event.target.matches('[data-close-modal]')) { state.modal = null; render(); }
  if (event.target.matches('[data-close-graph]')) { state.graphEmployee = null; render(); }
  if (event.target.closest('#add-requirement')) { const row = document.createElement('div'); row.className = 'requirement-row'; row.innerHTML = `<input name="skill-name" aria-label="Skill name" placeholder="e.g. Node.js" required><select name="skill-level" aria-label="Required proficiency"><option>Intermediate</option><option>Advanced</option><option>Expert</option><option>Beginner</option></select><button class="icon-btn remove-requirement" type="button" title="Remove skill" aria-label="Remove skill">${icon('close',14)}</button>`; document.getElementById('requirements-list').append(row); row.querySelector('input').focus(); }
  if (event.target.closest('.remove-requirement')) { if (document.querySelectorAll('.requirement-row').length > 1) event.target.closest('.requirement-row').remove(); else notify('Keep at least one required skill.'); }
});
appRoot.addEventListener('submit', async (event) => {
  event.preventDefault();
  if (event.target.id === 'evidence-policy-form') { const form = new FormData(event.target); const raw = String(form.get('evidenceDueDays') || '').trim(); try { const result = await fetch('/api/hr/settings', { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ evidenceDueDays: raw ? Number(raw) : null, allowedEmailDomains: String(form.get('allowedEmailDomains') || '').split(',').map(domain => domain.trim()).filter(Boolean) }) }); const data = await result.json(); if (!result.ok) throw new Error(data.error || 'Could not save policy.'); state.evidenceDueDays = data.evidenceDueDays; state.allowedEmailDomains = data.allowedEmailDomains || []; notify('Company settings saved. New evidence tasks use this deadline policy.'); state.modal = 'notifications'; render(); } catch (error) { notify(error.message, true); } return; }
  if (event.target.matches('.evidence-submit-form')) { const form = new FormData(event.target); const taskId = event.target.dataset.evidenceTask; try { await post(`/api/evidence/${encodeURIComponent(taskId)}/submit`, { evidenceType: form.get('evidenceType'), title: form.get('title'), description: form.get('description'), url: form.get('url') }); const [n, e] = await Promise.all([API('/api/notifications'), API('/api/evidence')]); state.notifications = n.notifications; state.evidenceTasks = e.tasks; state.modal = 'notifications'; render(); notify('Evidence submitted for review.'); } catch (error) { notify(error.message, true); } return; }
  if (event.target.id === 'invite-form') { const form = new FormData(event.target); try { const result = await post('/api/hr/invitations', { name: form.get('name'), email: form.get('email') }); state.modal = null; render(); notify(result.invitation.emailSent ? 'Invitation sent.' : (result.invitation.developmentAcceptanceUrl ? `Invitation created. Local acceptance link: ${result.invitation.developmentAcceptanceUrl}` : result.invitation.emailMessage)); } catch (error) { notify(error.message, true); } return; }
  if (event.target.id === 'auth-form') {
    const form = new FormData(event.target); const login = state.authMode === 'login'; const submit = event.target.querySelector('[type="submit"]'); submit.disabled = true;
    try { const response = await post(login ? '/api/login' : '/api/register', { name: form.get('name'), email: form.get('email'), password: form.get('password'), confirmPassword: form.get('confirmPassword') }); if (response.requiresVerification) { state.registrationMessage = response.message; state.verificationUrl = response.developmentVerificationUrl || ''; state.authMode = 'login'; render(); notify(response.message); return; } state.registrationMessage = ''; state.verificationUrl = ''; state.user = response.user; state.dashboard = null; state.section = 'dashboard'; state.matches = null; await refreshDashboard(); }
    catch (error) { notify(error.message, true); submit.disabled = false; }
  }
  if (event.target.id === 'talent-search') { const query = new FormData(event.target).get('query') || document.getElementById('search-query').value; await runSearch(query); }
  if (event.target.id === 'opening-form') {
    const form = event.target; const data = new FormData(form); const names = data.getAll('skill-name'); const levels = data.getAll('skill-level');
    try { await post('/api/openings', { title: data.get('title'), domain: data.get('domain'), duration: data.get('duration'), description: data.get('description'), requirements: names.map((name, index) => ({ name, level: levels[index] })) }); state.modal = null; await refreshDashboard(); notify('Project opening published.'); }
    catch (error) { notify(error.message, true); }
  }
  if (event.target.id === 'assessment-form') {
    const form = new FormData(event.target); const answers = state.dashboard.course.questions.map((_, index) => form.get(`question-${index}`));
    if (answers.some((answer) => answer === null)) { notify('Answer every question first.', true); return; }
    try { const result = await post('/api/learning/assessment', { answers }); await updateLearningView(); const output = document.getElementById('assessment-result'); if (output) output.textContent = `Score: ${result.score}% · ${result.correct}/${result.total} correct`; notify(`Assessment scored ${result.score}%.`); }
    catch (error) { notify(error.message, true); }
  }
  if (event.target.id === 'project-form') {
    const form = new FormData(event.target); const score = [0,1,2,3].reduce((total, index) => total + (form.has(`criterion-${index}`) ? 25 : 0), 0);
    try { const result = await post('/api/learning/project', { score }); await updateLearningView(); const output = document.getElementById('project-result'); if (output) output.textContent = `Rubric saved: ${result.score}%`; notify('Practical project rubric saved.'); }
    catch (error) { notify(error.message, true); }
  }
  if (event.target.id === 'skill-evidence-form') {
    const form = new FormData(event.target);
    const projectName = String(form.get('project-name') || '').trim();
    const projectDomain = String(form.get('project-domain') || '').trim() || 'General';
    const projectYear = Number(form.get('project-year')) || new Date().getFullYear();
    const projectLink = String(form.get('project-link') || '').trim();
    const projectSkills = String(form.get('project-skills') || '').split(',').map((item) => item.trim()).filter(Boolean);
    const certificationName = String(form.get('certification-name') || '').trim();
    if (!projectName) { notify('Add a project name before saving.', true); return; }
    try {
      const payload = {
        projects: [{
          name: projectName,
          domain: projectDomain,
          year: projectYear,
          link: projectLink,
          technologies: projectSkills.length ? projectSkills : ['Project Delivery']
        }],
        skills: projectSkills,
        certifications: certificationName ? [{ name: certificationName, year: projectYear, issuer: 'Self-reported' }] : []
      };
      const result = await post('/api/employee/skill-evidence', payload);
      state.dashboard.employee = result.employee;
      await refreshDashboard(false);
      render();
      notify('Project and certification evidence saved to your skill graph.');
      event.target.reset();
      const yearField = document.getElementById('project-year'); if (yearField) yearField.value = new Date().getFullYear();
    } catch (error) { notify(error.message, true); }
  }
});
async function boot() {
  try { const result = await API('/api/session'); state.user = result.user; if (state.user) await refreshDashboard(); else render(); }
  catch (error) { appRoot.innerHTML = `<div class="loading">Unable to connect to the workspace. ${escapeHTML(error.message)}</div>`; }
}
boot();
